git_vcs-exam-day-6:
function isFileIgnoredByGit(path, patterns) {
  let isIgnored = false;
  for (const pattern of patterns) {
    if (pattern.startsWith('#') || pattern.trim() === '') continue;
    if (pattern.startsWith('!')) {
      const p = pattern.slice(1);
      if (path.includes(p) || path.endsWith(p)) isIgnored = false;
      continue;
    }
    if (pattern.startsWith('/') && path.startsWith(pattern.slice(1))) isIgnored = true;
    else if (pattern.endsWith('/') && path.includes(pattern)) isIgnored = true;
    else if (pattern.startsWith('*') && path.endsWith(pattern.slice(1))) isIgnored = true;
    else if (path.includes(pattern) || path.endsWith(pattern)) isIgnored = true;
  }
  return {
    filePath: path,
    isIgnoredByGit: isIgnored,
    status: isIgnored ? 'FILE_IGNORED_BY_GITIGNORE_RULE' : 'FILE_TRACKED_IN_REPOSITORY'
  };
}

