git_vcs-exam-day-11:
function resolveMergeConflictBlock(rawText, choice) {
  const regex = /<<<<<<< HEAD\n([\s\S]*?)\n=======\n([\s\S]*?)\n>>>>>>> [a-zA-Z0-9_-]+/;
  const match = rawText.match(regex);
  if (!match) throw new Error('No conflict markers detected');
  const oursContent = match[1];
  const theirsContent = match[2];
  const resolvedContent = choice === 'OURS' ? oursContent : theirsContent;
  return {
    chosenSide: choice,
    resolvedText: resolvedContent,
    hasConflictMarkersRemaining: false,
    status: 'MERGE_CONFLICT_RESOLVED_CLEAN_NOMINAL'
  };
}

