git_vcs-exam-day-12:
function manageGitStashStack(stashes, action, payload) {
  const stack = [...stashes];
  if (action === 'PUSH') {
    stack.unshift({ id: `stash@{${stack.length}}`, message: payload.message, date: new Date().toISOString() });
    return { action, currentStack: stack, status: 'STASH_SAVED_NOMINAL' };
  }
  if (action === 'POP') {
    const popped = stack.shift();
    return { action, poppedItem: popped, remainingStack: stack, status: 'STASH_POPPED_NOMINAL' };
  }
  return { action: 'LIST', currentStack: stack, status: 'STASH_LISTED' };
}

