class IsrRingBuffer {
  constructor(capacity = 8) {
    this.capacity = capacity;
    this.buffer = new Array(capacity);
    this.head = 0; // Written by ISR
    this.tail = 0; // Read by Main thread
  }
  pushFromIsr(val) {
    const nextHead = (this.head + 1) % this.capacity;
    if (nextHead === this.tail) return { success: false, error: 'ISR_BUFFER_OVERRUN' };
    this.buffer[this.head] = val;
    this.head = nextHead;
    return { success: true };
  }
  popInMainThread() {
    if (this.head === this.tail) return null; // Empty
    const val = this.buffer[this.tail];
    this.tail = (this.tail + 1) % this.capacity;
    return val;
  }
}

