function acquireMutexWithPriorityInheritance(mutex, task) {
  if (!mutex.isLocked) {
    mutex.isLocked = true;
    mutex.owner = task;
    return { success: true, effectivePriority: task.priority };
  }
  // Mutex is locked by another task
  if (task.priority > mutex.owner.effectivePriority) {
    mutex.owner.effectivePriority = task.priority; // Priority Inheritance Boost!
    return { success: false, priorityInversionAvoided: true, boostedOwnerPriority: task.priority };
  }
  return { success: false, priorityInversionAvoided: false };
}

