    this.currentSector = 0;
    this.sectorEntries = 0;
    this.latestData = null;
  }
  writeEntry(data) {
    if (this.sectorEntries >= this.capacity) {
      this.currentSector = (this.currentSector + 1) % this.sectorCount;
      this.eraseCounts[this.currentSector]++; // Sector Erase
      this.sectorEntries = 0;
    }
    this.sectorEntries++;
    this.latestData = data;
    return { sector: this.currentSector, entryIndex: this.sectorEntries - 1, eraseCount: this.eraseCounts[this.currentSector] };
