  return { success: true, executedAmount: amount, status: 'FUNCTION_EXECUTION_SUCCESSFUL' };
}

blockchain-exam-day-12:
function packVariablesIntoSlots(vars) {
  // vars = [{ name: 'a', bytes: 20 }, { name: 'b', bytes: 8 }, { name: 'c', bytes: 4 }]
  let slots = 1;
  let currentSlotBytes = 0;
  for (const v of vars) {
    if (currentSlotBytes + v.bytes > 32) {
      slots++;
      currentSlotBytes = v.bytes;
    } else {
      currentSlotBytes += v.bytes;
    }
  }
  return {
    totalVariables: vars.length,
    totalSlotsUsed: slots,
    totalGasSavingsVsUnpacked: (vars.length - slots) * 20000
  };
}

blockchain-exam-day-13:
function executeErc20TransferFrom(balances, allowances, spender, from, to, amount) {
  const fromBal = balances[from] || 0;
  const allowKey = `${from}_${spender}`;
  const allowed = allowances[allowKey] || 0;
  if (fromBal < amount) return { success: false, error: 'ERC20_INSUFFICIENT_BALANCE' };
  if (allowed < amount) return { success: false, error: 'ERC20_INSUFFICIENT_ALLOWANCE' };
  balances[from] -= amount;
  balances[to] = (balances[to] || 0) + amount;
  allowances[allowKey] -= amount;
  return {
    success: true,
    fromNewBalance: balances[from],
    toNewBalance: balances[to],
    remainingAllowance: allowances[allowKey]
  };
}

blockchain-exam-day-14:
function transferErc721Token(ledger, caller, from, to, tokenId) {
  const token = ledger[tokenId];
  if (!token) return { success: false, error: 'ERC721_NONEXISTENT_TOKEN' };
  if (token.owner.toLowerCase() !== from.toLowerCase()) return { success: false, error: 'ERC721_FROM_IS_NOT_OWNER' };
  const isAuthorized = (caller.toLowerCase() === from.toLowerCase()) || (token.approved.toLowerCase() === caller.toLowerCase());
  if (!isAuthorized) return { success: false, error: 'ERC721_CALLER_NOT_OWNER_NOR_APPROVED' };
  token.owner = to;
  token.approved = '0x0000000000000000000000000000000000000000'; // Reset approval on transfer
  return { success: true, tokenId, newOwner: to, status: 'NFT_TRANSFER_CONFIRMED' };
}

