    healthFactor: Number(healthFactor.toFixed(2)),
    isSafe: isSolvent,
    status: isSolvent ? 'DEFI_POSITION_SOLVENT_HEALTHY' : 'LIQUIDATION_RISK_HEALTH_BELOW_1'
  };
}

