function calculateVertexLayout(attributes) {
  // attributes = [{ name: 'position', size: 3 }, { name: 'normal', size: 3 }, { name: 'uv', size: 2 }]
  let currentOffset = 0;
  const layout = {};
  for (const attr of attributes) {
    const byteSize = attr.size * 4; // 4 bytes per Float32
    layout[attr.name] = { size: attr.size, offset: currentOffset, byteSize };
    currentOffset += byteSize;
  }
  return { totalStrideBytes: currentOffset, attributes: layout };
}

g3d-exam-day-9:
function calculateBlinnPhong(n, l, v, shininess = 32) {
  const ambient = 0.1;
  // Diffuse: max(dot(N, L), 0)
  const nDotL = Math.max(0, n[0]*l[0] + n[1]*l[1] + n[2]*l[2]);
  const diffuse = nDotL * 0.7;
  // Halfway vector H = normalize(L + V)
  const hx = l[0] + v[0], hy = l[1] + v[1], hz = l[2] + v[2];
  const hMag = Math.sqrt(hx*hx + hy*hy + hz*hz);
  const h = [hx/hMag, hy/hMag, hz/hMag];
  const nDotH = Math.max(0, n[0]*h[0] + n[1]*h[1] + n[2]*h[2]);
  const specular = Math.pow(nDotH, shininess) * 0.5;
  return Number((ambient + diffuse + specular).toFixed(3));
}

