}

g3d-exam-day-19:
function slerpQuaternion(q1, q2, t) {
  let dot = q1[0]*q2[0] + q1[1]*q2[1] + q1[2]*q2[2] + q1[3]*q2[3];
  let targetQ = [...q2];
  if (dot < 0.0) {
    dot = -dot;
    targetQ = targetQ.map(v => -v); // Shortest path flip
  }
  if (dot > 0.9995) {
    // LERP fallback for tiny angles
    const res = q1.map((v, i) => v + t * (targetQ[i] - v));
    return res.map(v => Number(v.toFixed(3)));
  }
  const theta = Math.acos(dot);
  const sinTheta = Math.sin(theta);
  const w1 = Math.sin((1.0 - t) * theta) / sinTheta;
  const w2 = Math.sin(t * theta) / sinTheta;
  const result = q1.map((v, i) => w1 * v + w2 * targetQ[i]);
  return result.map(v => Number(v.toFixed(3)));
}

