  // deltas = { jawOpen: [0, -0.2, 0], mouthSmile: [0.1, 0.05, 0] }
  // weights = { jawOpen: 0.5, mouthSmile: 0.8 }
  let morphedX = baseVertex[0];
  let morphedY = baseVertex[1];
  let morphedZ = baseVertex[2];
  for (const [shapeName, weight] of Object.entries(weights)) {
