iot_edge-exam-day-3:
function allocateTensorArena(layerSizes) {
  let offset = 0;
  const tensorOffsets = [];
  for (let i = 0; i < layerSizes.length; i++) {
    const size = layerSizes[i];
    // 16-byte alignment invariant for SIMD instructions
    const alignedOffset = Math.ceil(offset / 16) * 16;
    tensorOffsets.push({ tensorIndex: i, byteSize: size, arenaOffset: alignedOffset });
    offset = alignedOffset + size;
  }
  return {
    totalArenaBytesRequired: offset,
    tensorAllocations: tensorOffsets,
    status: 'TENSOR_ARENA_STATICALLY_ALLOCATED_ZERO_HEAP'
  };
}

iot_edge-exam-day-4:
function quantizeFloatArrayToInt8(arr, rMin, rMax) {
  const S = (rMax - rMin) / 255;
  const Z = Math.round(-rMin / S) - 128;
  const quantized = arr.map(r => {
    const q = Math.round((r - rMin) / S) - 128;
    return Math.max(-128, Math.min(127, q));
  });
  return {
    scale: Number(S.toFixed(6)),
    zeroPoint: Z,
    quantizedInt8: quantized,
    compressionRatio: '4X_REDUCTION_VS_FLOAT32',
    status: 'QUANTIZATION_INT8_SUCCESS'
  };
}

iot_edge-exam-day-5:
function runInt8InferenceKernel(inputs, weights, bias, scale, zp) {
  let acc = bias;
  for (let i = 0; i < inputs.length; i++) {
    acc += inputs[i] * weights[i];
  }
  // Fixed-point scale multiplier simulation
  const rawOutput = Math.round(acc * scale) + zp;
  const clamped = Math.max(-128, Math.min(127, rawOutput));
  return {
    accumulatorRawInt32: acc,
    quantizedOutputInt8: clamped,
    status: 'TINYML_INT8_INFERENCE_CYCLE_COMPLETE'
  };
}

iot_edge-exam-day-6:
function applyHammingWindow(buffer, fs, fMax) {
  const isAliasingHazard = fs < (2 * fMax);
  const N = buffer.length;
  const windowed = buffer.map((val, n) => {
    const w = 0.54 - 0.46 * Math.cos((2 * Math.PI * n) / (N - 1));
    return Number((val * w).toFixed(4));
  });
  return {
    samplesCount: N,
    samplingRateHz: fs,
    nyquistSatisfied: !isAliasingHazard,
    windowedSignal: windowed,
    status: isAliasingHazard ? 'ALIASING_HAZARD_INCREASE_SAMPLING_RATE' : 'WINDOWING_APPLIED_NYQUIST_VALID'
  };
}

iot_edge-exam-day-7:
function extractFftPeakFeatures(reals, imags, fs = 1600) {
  const N = reals.length;
  const binWidth = fs / N;
  let maxMag = -1;
  let peakBin = 0;
  const magnitudes = [];
  for (let k = 0; k < N / 2; k++) { // Only positive frequencies
    const mag = Math.sqrt(reals[k] * reals[k] + imags[k] * imags[k]);
    magnitudes.push(Number(mag.toFixed(2)));
    if (mag > maxMag) {
      maxMag = mag;
      peakBin = k;
    }
  }
  const peakFreqHz = peakBin * binWidth;
  return {
    binWidthHz: Number(binWidth.toFixed(2)),
    peakFrequencyHz: Number(peakFreqHz.toFixed(1)),
    peakMagnitude: Number(maxMag.toFixed(2)),
    magnitudes,
    status: 'FFT_FEATURE_EXTRACTION_SUCCESS'
  };
}

iot_edge-exam-day-8:
function calculateMelEnergy(energies, freqs, centerHz, bwHz) {
  let totalEnergy = 0;
  for (let i = 0; i < freqs.length; i++) {
    const f = freqs[i];
    const dist = Math.abs(f - centerHz);
    if (dist < bwHz) {
      const weight = 1 - (dist / bwHz); // Triangular filter weighting
      totalEnergy += energies[i] * weight;
    }
  }
  const logMelEnergy = Math.log(Math.max(1e-6, totalEnergy));
  return {
    melCenterHz: centerHz,
    rawMelEnergy: Number(totalEnergy.toFixed(3)),
    logMelEnergy: Number(logMelEnergy.toFixed(3)),
    status: 'MFCC_FILTERBANK_INTEGRATED'
  };
}

iot_edge-exam-day-9:
function evaluateVibrationAnomaly(samples, mean, std) {
  let sumSq = 0;
  let sumFourth = 0;
  const N = samples.length;
  for (const s of samples) {
    sumSq += s * s;
    const diff = s - mean;
    sumFourth += Math.pow(diff, 4);
  }
  const rms = Math.sqrt(sumSq / N);
  const kurtosis = (sumFourth / N) / Math.pow(std, 4);
  const isAnomaly = (rms > mean + 3 * std) || (kurtosis > 4.5);
  return {
    rms: Number(rms.toFixed(2)),
    kurtosis: Number(kurtosis.toFixed(2)),
    isAnomaly,
    status: isAnomaly ? 'BEARING_ANOMALY_VIBRATION_SPIKE' : 'VIBRATION_NORMAL_HEALTHY'
  };
}

