iot_edge-exam-day-11:
function simCmsisNnDotProduct(vecA, vecB) {
  // CMSIS-NN arm_nn_vec_mat_mult_t_s8 processes 4 INT8s per SIMD instruction
  let sum = 0;
  const quadCount = Math.floor(vecA.length / 4);
  for (let q = 0; q < quadCount; q++) {
    const idx = q * 4;
    sum += (vecA[idx] * vecB[idx]) + (vecA[idx+1] * vecB[idx+1]) + (vecA[idx+2] * vecB[idx+2]) + (vecA[idx+3] * vecB[idx+3]);
  }
  return {
    simdQuadsProcessed: quadCount,
    accumulatorResult: sum,
    cyclesEquivalent: quadCount, // 1 cycle per 4 MACs with SIMD!
    status: 'CMSIS_NN_SIMD_ACCELERATION_SUCCESS'
  };
}

