      zeros++;
      return 0;
    }
    return w;
  });
  const sparsity = (zeros / total) * 100;
  return {
    totalParameters: total,
    zeroedParameters: zeros,
    sparsityPercent: Number(sparsity.toFixed(1)),
    prunedWeights: pruned,
    status: 'WEIGHT_PRUNING_SUCCESS'
  };
}

iot_edge-exam-day-13:
function calculateDepthwiseMacSavings(H, W, Cin, Cout, K = 3) {
  const standardMacs = H * W * Cin * Cout * K * K;
  const depthwiseMacs = H * W * Cin * K * K;
  const pointwiseMacs = H * W * Cin * Cout * 1 * 1;
  const separableMacs = depthwiseMacs + pointwiseMacs;
  const reductionPercent = ((standardMacs - separableMacs) / standardMacs) * 100;
  return {
    standardConvMacs: standardMacs,
    depthwiseSeparableMacs: separableMacs,
    computationReductionPercent: Number(reductionPercent.toFixed(1)),
    theoreticalSpeedupRatio: Number((standardMacs / separableMacs).toFixed(1)),
    status: 'DEPTHWISE_SEPARABLE_OPTIMAL'
  };
}

