function cleanDataAndFilterOutliers(raw) {
  const valid = raw.filter(v => v !== null && v !== undefined && !isNaN(v)).sort((a, b) => a - b);
  const n = valid.length;
  const median = n % 2 === 1 ? valid[Math.floor(n / 2)] : (valid[n / 2 - 1] + valid[n / 2]) / 2;
  const imputed = raw.map(v => (v === null || v === undefined || isNaN(v)) ? median : v).sort((a, b) => a - b);
  const q1 = imputed[Math.floor(imputed.length * 0.25)];
  const q3 = imputed[Math.floor(imputed.length * 0.75)];
  const iqr = q3 - q1;
  const lowerBound = q1 - 1.5 * iqr;
  const upperBound = q3 + 1.5 * iqr;
  const cleaned = imputed.filter(v => v >= lowerBound && v <= upperBound);
  return {
    imputedMedianUsed: median,
    iqrValue: iqr,
    cleanCount: cleaned.length,
    cleanedDataset: cleaned,
    status: 'DATA_CLEANING_COMPLETED'
  };
}

bcom_ana-exam-day-4:
function calculatePearsonCorrelation(x, y) {
  const n = x.length;
  const meanX = x.reduce((a, b) => a + b, 0) / n;
  const meanY = y.reduce((a, b) => a + b, 0) / n;
  let num = 0;
  let denX = 0;
  let denY = 0;
  for (let i = 0; i < n; i++) {
    const dx = x[i] - meanX;
    const dy = y[i] - meanY;
    num += dx * dy;
    denX += dx * dx;
    denY += dy * dy;
  }
  const r = num / Math.sqrt(denX * denY);
  return {
    samplePoints: n,
    pearsonR: Number(r.toFixed(4)),
    relationship: r > 0.8 ? 'STRONG_POSITIVE_CORRELATION' : (r < -0.8 ? 'STRONG_NEGATIVE_CORRELATION' : 'MODERATE_WEAK_CORRELATION'),
    status: 'CORRELATION_COMPUTED'
  };
}

