bcom_ait-exam-day-3:
function calculateCosineSimilarity(a, b) {
  let dot = 0, magA = 0, magB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    magA += a[i] * a[i];
    magB += b[i] * b[i];
  }
  const sim = dot / (Math.sqrt(magA) * Math.sqrt(magB));
  const isRelevant = sim >= 0.85;
  return {
    cosineSimilarity: Number(sim.toFixed(2)),
    isHighlyRelevantChunk: isRelevant,
    status: isRelevant ? 'RAG_CHUNK_RETRIEVED_AND_GROUNDED' : 'LOW_SIMILARITY_DISCARDED'
  };
}

