function getMinGpuUtilizationBenchmark(candidateValue) {
  if (candidateValue === undefined) return 75;
  return { benchmark: 75, candidate: candidateValue, meetsBenchmark: candidateValue >= 75, delta: Number((candidateValue - 75).toFixed(4)) };
}

