function runSyntheticMarketSimulation(personas, conversionPct) {
  const projectedPurchasers = Math.round(personas * (conversionPct / 100));
  return {
    simulatedPersonasCount: personas,
    targetPurchaseConversionPercent: conversionPct,
    projectedPurchasersCount: projectedPurchasers,
    status: 'SYNTHETIC_MARKET_SIMULATION_COMPLETED'
  };
}

