function getSyntheticDataBenefit(inputTag) {
  if (inputTag === undefined) return "PRIVACY_PRESERVING_RAPID_MARKET_STRESS_TESTING";
  const normalized = String(inputTag).trim();
  return { canonical: "PRIVACY_PRESERVING_RAPID_MARKET_STRESS_TESTING", provided: normalized, isMatch: normalized.toUpperCase() === "PRIVACY_PRESERVING_RAPID_MARKET_STRESS_TESTING".toUpperCase() };
}

bcom_ait-exam-day-28:
function compareBuildVsBuyTco(buildY1, buildMaint, buyY1, buyAnnual) {
  const build3YrTco = buildY1 + (2 * buildMaint);
  const buy3YrTco = buyY1 + (2 * buyAnnual);
  const recommended = build3YrTco < buy3YrTco ? 'BUILD_CUSTOM_INTERNAL_IP' : 'BUY_ENTERPRISE_COMMERCIAL_SAAS';
  return {
    buildThreeYearTcoUsd: build3YrTco,
    buyThreeYearTcoUsd: buy3YrTco,
    strategicRecommendation: recommended,
    status: 'TCO_EVALUATED'
  };
}

