bcom_aud-exam-day-1:
function evaluateDay1AuditMetric(primaryMetric, secondaryMetric, hurdleThreshold = 71) {
  const weightedScore = Number(((primaryMetric * 0.6) + (secondaryMetric * 0.4)).toFixed(2));
  const isCompliant = weightedScore >= hurdleThreshold;
  return {
    day: 1,
    weightedScore,
    hurdleThreshold,
    isCompliant,
    status: isCompliant ? 'STATUTORY_AUDIT_DAY_1_COMPLIANT' : 'STATUTORY_AUDIT_DAY_1_VARIANCE_ALERT'
  };
}

bcom_aud-assign-day-1:
function calculateDay1VarianceIndex(observedValue, benchmarkValue) {
  if (!benchmarkValue || benchmarkValue <= 0) throw new Error('Benchmark must be positive');
  const varianceAmount = Number((observedValue - benchmarkValue).toFixed(2));
  const variancePct = Number(((varianceAmount / benchmarkValue) * 100).toFixed(2));
  return {
    observedValue,
    benchmarkValue,
    varianceAmount,
    variancePct,
    withinTolerance: Math.abs(variancePct) <= 10
  };
}

