function calculateDay30VarianceIndex(observedValue, benchmarkValue) {
  if (!benchmarkValue || benchmarkValue <= 0) throw new Error('Benchmark must be positive');
  const varianceAmount = Number((observedValue - benchmarkValue).toFixed(2));
  const variancePct = Number(((varianceAmount / benchmarkValue) * 100).toFixed(2));
  return {
    observedValue,
    benchmarkValue,
    varianceAmount,
    variancePct,
    withinTolerance: Math.abs(variancePct) <= 10
  };
}
